        { "attribute": "number_of_verification_scale_intervals_n", "class_XIII_group_1": "≤ 7500 (1)", "class_Y_group_1": "≤ 6000 (1)", "class_XIII_group_2": "≤ 3750 (1)", "class_Y_group_2": "≤ 3750 (1)" },
